#!/usr/bin/env bash
# Generates the two generated files of src/driver/ without .NET (spec 019 R15, R28), byte for byte what the xUnit
# generators wrote under BAYAN_UPDATE=1:
#   src/driver/diagdocs.byn  one constant per docs/diagnostics/BYN####.md (SelfhostDefaultT1Tests.Generate)
#   src/driver/runtime.byn   runtime/bayan-rt.h and bayan-rt.c as raw strings (SelfhostDriverRuntimeTests.Generate)
#   gen-driver-files.sh diagdocs|runtime   print one
#   gen-driver-files.sh --write            write both
#   gen-driver-files.sh --check            exit 1 naming each committed file that differs from a fresh generation
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
die() { echo "gen-driver-files: $*" >&2; exit 1; }
export LC_ALL=C

# Each docs/diagnostics/BYN*.md (ordinal order) as a string constant: \ " \n \r \t escaped, other controls as \u{hex}.
diagdocs() {
  local files=() f n
  for f in "$root"/docs/diagnostics/BYN*.md; do [ -f "$f" ] && files+=("$f"); done
  [ ${#files[@]} -gt 0 ] || die "no docs/diagnostics/BYN*.md"
  printf '// GENERATED by SelfhostDefaultT1Tests (BAYAN_UPDATE=1): one constant per docs/diagnostics/BYN####.md (spec 017 plan D2). Do not edit.\n\n'
  for f in "${files[@]}"; do
    n="$(basename "$f" .md)"
    printf 'const doc%s: string = "' "${n#BYN}"
    perl -0777 -pe 's/([\\"\x00-\x1f])/$1 eq "\\" ? "\\\\" : $1 eq "\"" ? "\\\"" : $1 eq "\n" ? "\\n" : $1 eq "\r" ? "\\r" : $1 eq "\t" ? "\\t" : sprintf("\\u{%x}", ord $1)/ge' "$f"
    printf '"\n'
  done
  printf '\n/// The text of `docs/diagnostics/<name>.md` for an upper-case code, or null when there is none.\n'
  printf 'string? diagDoc(string name) {\n    switch name {\n'
  for f in "${files[@]}"; do
    n="$(basename "$f" .md)"
    printf '        case "%s":\n            return doc%s\n' "$n" "${n#BYN}"
  done
  printf '        default:\n            return null\n    }\n}\n'
}

# runtime/bayan-rt.h and bayan-rt.c, CRLF made LF, as raw-string constants; refuses text a raw string cannot hold.
runtime() {
  local name file text
  printf '// Generated by SelfhostDriverRuntimeTests under BAYAN_UPDATE=1 from runtime/; do not edit.\n'
  for pair in runtimeHeader:bayan-rt.h runtimeSource:bayan-rt.c; do
    name="${pair%%:*}"; file="$root/runtime/${pair#*:}"
    [ -f "$file" ] || die "runtime/${pair#*:} not found"
    text="$(perl -0777 -pe 's/\r\n/\n/g' "$file"; printf x)"; text="${text%x}"
    case "$text" in *'"""'*) die "runtime/${pair#*:} holds \"\"\"" ;; $'\n'*|*'"') die "runtime/${pair#*:} cannot be a raw string" ;; esac
    printf '\nconst %s: string = """%s"""\n' "$name" "$text"
  done
}

case "${1:-}" in
  diagdocs) diagdocs ;;
  runtime) runtime ;;
  --write) diagdocs > "$root/src/driver/diagdocs.byn"; runtime > "$root/src/driver/runtime.byn" ;;
  --check)
    stale=()
    for g in diagdocs runtime; do
      cmp -s <("$g") "$root/src/driver/$g.byn" || stale+=("src/driver/$g.byn")
    done
    [ ${#stale[@]} = 0 ] || die "$(printf '%s ' "${stale[@]}")differs from a fresh generation; run bash scripts/selfhost/gen-driver-files.sh --write"
    ;;
  *) die "usage: gen-driver-files.sh diagdocs|runtime|--write|--check" ;;
esac
